**Audit Analytics;
data restate; set data.auditnonreli_95_20; run;
data restate2; set restate; 

CIK=trim(company_fkey);  
start=RES_BEGIN_DATE;	end=res_end_date; 

if nmiss(start,end,cik)=0;

FRAUD=RES_FRAUD  ;
SEC=RES_SEC_INVEST;
ACCTG_CODE=RES_ACC_RES_FKEY_LIST ;

Restate=1;

if SEC=1 or Fraud=1 then RestateHLM=1; else RestateHLM=0; *apply Hennes-Leone-Miller (TAR, 2008) classification rule (either "fraud" or "irregularity" or "SEC investigation");

begyear=year(res_begin_date);
fileyear=year(file_date);

keep res_notif_key cik file_date start end begyear fileyear restate restatehlm FRAUD SEC date_of_8k_402 form_fkey; 
run; 
proc means data=restate2 mean n nmiss; var restate restatehlm FRAUD SEC; run; *Audit Analytics non-reliance dataset "Tracks 4.02 non-reliance disclosures made since August of 2004.";

proc import datafile="[redacted-path-a4a1a5549170]" out=data.AArestatements (rename=(cik_code=cik restatement_key=res_notif_key)) dbms=XLSX replace; sheet='restatement-data1604697840';getnames=yes;run; *add BIAS FROM AUDIT ANALYTICS SUPPLEMENTAL DATA;

proc sort data=restate2 nodupkey; by res_notif_key; run; 
proc sort data=data.AArestatements nodupkey out=AArestatements; by res_notif_key; where res_notif_key>0; run;
proc sql;
      create table restate3 as select unique a.*, ((cumulative_change_in_net_income*-1)/1000000) as restate_amt, disclosure_date
      from restate2 a left join AArestatements b on a.res_notif_key=b.res_notif_key;
quit;
data restate4; set restate3; 
format start end date9.; nyears=ceil((intck('month',start,end)+1)/12);
restate_amt_adj=restate_amt/nyears;
run;

** IBES;
data statsum; set data.statsum_Jan90_Dec19_eps1;
if fpi=1;
if statpers<fpedats;
run;
proc sort data = statsum; by ticker fpedats descending statpers;
proc sort data = statsum nodupkey; by ticker fpedats; run;
proc sql; 
	create table statsum as select a.*, b.permno, b.score from statsum a left join data.ibcrsphist_jul20 b on a.ticker=b.ticker and b.sdate<=a.statpers<=b.edate;
quit; 
data statsum; set statsum; if missing(permno) then delete; run;
proc sort data = statsum; by ticker fpedats score; run;
proc sort data = statsum nodupkey; by ticker fpedats; run;
proc sort data = statsum; by permno fpedats score; run;
proc sort data = statsum nodupkey; by permno fpedats; run; *when multiple matches, only leave the match with the lowest score (=most accurate);

** Thomson 13;
data inst; set data.tfn_Jan1995_Dec2018_s34; run;
data inst; set inst; pct=shares/(shrout1*1000000); run;
proc sql; create table inst as select *, sum(pct) as instown, count(distinct mgrno) as numinst from inst group by cusip, rdate; quit;
proc sort data=inst nodupkey; by cusip rdate; run;
data inst; set inst; if not missing(cusip); run;
proc means data = inst min p1 mean p99 max;
var instown numinst;
run;
data inst; set inst; if instown<0 then instown=0; if instown>1 then instown=1; run;

