proc import datafile="[redacted-path-3a87d0bcc23a]"
out=index dbms=dlm replace;
delimiter='09'x;
getnames=yes;
run;
proc sort data = index; by cik accession form; run;
proc sort data = index nodupkey; by cik accession; run;

data alledgars; set alledgar:; run; *merge all;

proc sql; create table alledgar2 as select a.*, b.form, b.accession as accession2
from alledgars as a left join index as b on a.cik=b.cik and a.accession=b.accession; quit;
proc freq data= alledgar2;
table form;
run;
data alledgar3; set alledgar2; if not missing(form); run;

data alledgar_daily; set alledgar3; 
if form='8-K' then do; drtpv8k=drtpv; end;
if form='4' then do; drtpv4=drtpv; end;
if form in ('10-Q', '10-Q/A', '10QSB', '10-QSB', '10QSB/A', '10-QT', '10-QT/A') then do; drtpv10qs=drtpv; end;
if form in ('10-K','10-K/A','10-K405','10-K405/','10KSB','10-KSB','10KSB/A','10-KSB/A','10KSB40','10KSB40/','10-KT','10-KT/A','10KT405','10KT405/') then do; drtpv10ks=drtpv; end;
if form in ('DEF 14A','DEF 14C','DEFA14A','DEFA14C','DEFC14A','DEFC14C','DEFR14A','DEFR14C','DEFS14A','DEFS14C','PREA14A','PREC14A','PREC14C','PRER14A','PRER14C','PRES14A','PRES14C') then do; drtpvdefs=drtpv; end;
run;

proc sql; create table alledgar_daily as select unique cik, date,
sum(drtpv) as drtpv,
sum(drtpv8k) as drtpv8k, 
sum(drtpv4) as drtpv4, 
sum(drtpv10qs) as drtpv10qs, 
sum(drtpv10ks) as drtpv10ks, 
sum(drtpvdefs) as drtpvdefs
from alledgar_daily group by cik,date; quit;

data alledgar_daily; set alledgar_daily; 
array variable {5} drtpv8k drtpv4 drtpv10qs drtpv10ks drtpvdefs;
do i=1 to 5;
if missing(variable[i]) then variable[i]=0;
end;
run;

data alledgar; set alledgar_daily;
cik10=put(cik,z10.);
run;

proc sql; create table dat4 as select unique a.*, 
sum(b.drtpv) as drtpv,
sum(b.drtpv8k) as drtpv8k,
sum(b.drtpv4) as drtpv4,
sum(b.drtpv10qs) as drtpv10qs,
sum(b.drtpv10ks) as drtpv10ks,
sum(b.drtpvdefs) as drtpvdefs
from dat3 as a left join alledgar as b 
on a.cik=b.cik10 and intnx('month',a.datadate,-11,'beg')<=b.date<=intnx('month',a.datadate,0,'end')
group by a.cik,a.datadate; quit;
data dat4; set dat4;
searchtot=drtpv/10000; 
search8k=drtpv8k/10000;
search4=drtpv4/10000; 
search10qs=drtpv10qs/10000; 
search10ks=drtpv10ks/10000;
searchdefs=drtpvdefs/10000; 
run;
data dat4; set dat4;
searchfunda=search10qs+search10ks;
searchinc=searchdefs+search4;
run;

data data_final; set dat7a; run;
data data.data_final; set data_final; run;



*3. MAIN SAMPLE;
data main; set data_final;
if fyear>=2005;
if fyear<=2016;
run;
proc sql; create table main as select * from main 
where (prcc_f_lag1>=5 and prcc_f>=5 and bhr3count=12); quit;
%delete_missing(main, size lbtm btm roa leverage return capital intangibles financing acq ic sale_gr searchfunda searchinc persistpx loss aret3r bhaer3 epspx epspx_lag1 prcd_y betaff);
proc sql; create table main as select *, count(fyear) as countyear 
from main 
group by cik having countyear >= 5; quit;
%winsor(dsetin=main, dsetout=main, vars=epspx epspx_lag1 prcd_y, byvar=none, type=delete, pctl=1 99);
data main; set main;
sur_eps=(epspx-epspx_lag1)/prcd_y;
run;
%winsor(dsetin=main, dsetout=main, vars=bias_atlag_lead1 searchfunda searchinc bhaer3 betaff btm capital financing intangibles instown ic leverage numest persistpx return retvol roa sale_gr shortint size sur_eps, byvar=fyear, type=winsor, pctl=1 99);
data main; set main;
bias_lead1=bias_atlag_lead1*10000; *expressed in basis points;
if restatehlm_lead1=0 then bias_lead1=0;
run;



*4. EXPORT;
proc export data = main dbms = dta outfile = '[redacted-path-134635062fc0]' replace; run;

data xtemp;
    set &dsetin;
    run;

proc univariate data = xtemp noprint;
    by &byvar;
    var &vars;
    output out = xtemp_pctl PCTLPTS = &pctl PCTLPRE = &vars PCTLNAME = L H;
    run;

data &dsetout;
    merge xtemp xtemp_pctl;

%macro delete_missing(dataset, varlist);
  data &dataset;
    set &dataset;
    array vars &varlist;
    do i = 1 to dim(vars);
      if missing(vars[i]) then delete;
    end;
  run;
%mend;

proc sql; create table persist_reg as select a.*, b.epspx, b.epspx_lag, b.fyear as fyears_lag
from persist_reg as a left join persist as b on a.cik=b.cik and a.fyear-9<=b.fyear<=a.fyear; quit;
proc sort data = persist_reg; by cik fyear fyears_lag; run;

proc reg data = persist_reg noprint outest=px_persist edf;
model epspx=epspx_lag;
by cik fyear;

proc sql;
create table addlagyear2 as
select a.*, b.rect as rect_m2
from addlagyear1 a inner join funda b
on a.gvkey=b.gvkey and a.fyear-2=b.fyear;
quit;

data rdq; set rdq; if fqtr=4; run;
proc sort data = rdq; by gvkey fyearq; run;
data rdq; set rdq;
format rdq_lag date9.;
if lag(gvkey)=gvkey and lag(fyearq)=fyearq-1 then lag1=1; else lag1=.;
rdq_lag=lag1*lag(rdq);
run;

proc sql; create table dat4 as select a.*, b.rdq, b.rdq_lag
from dat4 as a left join rdq as b
on a.gvkey=b.gvkey and a.datadate=b.datadate; quit;

proc sql; create table dat5d as select unique a.*, exp(sum(log(1+(b.ret-b.ewretd))))-1 as bhaer3, count(b.ret) as bhr3count
from dat5c as a left join msf as b on a.permno=b.permno and intnx('month',a.datadate,-8,'beg')<=b.date<=intnx('month',a.datadate,+3,'end') group by a.cik, a.datadate; quit;

proc sql; create table dat5e as select unique a.*, exp(sum(log(1+b.ret-b.sprtrn)))-1 as aret3r, count(b.ret) as countret3r 
from dat5d as a left join dsf as b on a.permno=b.permno and intnx('weekday',a.rdq,-1)<=b.date<=intnx('weekday',a.rdq,+1)
group by a.cik,a.datadate; quit;

data dat7; set dat6;
if lag(cik)=cik and lag(fyear)=fyear-1 then lag1=1; else lag1=.;
sale_lag1 = lag1*lag1(sale);
sale_gr = (sale-sale_lag1)/sale_lag1;
run;
proc sort data = dat7; by cik descending fyear; run;
data dat7; set dat7;
if lag(cik)=cik and lag(fyear)=fyear+1 then lead1=1; else lead1=.;
bias_atlag_lead1 = lead1*lag1(bias_atlag);
fscore_lead1 = lead1*lag1(fscore);
run;
